import React from 'react';
import { View, Text, StyleSheet } from 'react-native';
import { PatternType } from './theme';

interface Props {
  pattern: PatternType;
  color: string;
  children: React.ReactNode;
  style?: object;
}

// パターンごとの絵文字・記号タイル
const PATTERN_CHARS: Record<PatternType, string> = {
  none: '',
  dots: '·',
  stripes: '/',
  grid: '+',
  waves: '~',
  diamonds: '◇',
};

const PATTERN_SIZES: Record<PatternType, number> = {
  none: 0,
  dots: 18,
  stripes: 16,
  grid: 20,
  waves: 18,
  diamonds: 22,
};

// children を安全にレンダリングするヘルパー
// View の直接の子に生テキストがあると
// 「Unexpected text node: A text node cannot be a child of a <View>」になるため、Text でラップする。
const renderSafeChildren = (children: React.ReactNode): React.ReactNode => {
  if (children == null) return null;

  if (typeof children === 'string') {
    return <Text>{children}</Text>;
  }

  if (Array.isArray(children)) {
    return children.map((child, index) => {
      if (typeof child === 'string') {
        return <Text key={index}>{child}</Text>;
      }
      if (Array.isArray(child)) {
        return renderSafeChildren(child);
      }
      return child;
    });
  }

  return children;
};

export default function PatternBackground({ pattern, color, children, style }: Props) {
  if (pattern === 'none') {
    return <View style={[styles.container, style, { backgroundColor: 'transparent' }]}>{renderSafeChildren(children)}</View>;
  }

  const char = PATTERN_CHARS[pattern];
  const size = PATTERN_SIZES[pattern];
  const cols = 20;
  const tiles = Array.from({ length: cols * 40 });

  return (
    <View style={[styles.container, style, { backgroundColor: 'transparent' }]}>
      {/* Pattern overlay */}
      <View style={[StyleSheet.absoluteFill, { pointerEvents: 'none' }]}>
        <View style={styles.patternWrap}>
          {tiles.map((_, i) => (
            <Text
              key={i}
              style={{
                width: size,
                height: size,
                fontSize: size * 0.6,
                color: color + '25',
                textAlign: 'center',
                lineHeight: size,
              }}
            >
              {char}
            </Text>
          ))}
        </View>
      </View>
      {renderSafeChildren(children)}
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1 },
  patternWrap: {
    flex: 1,
    flexDirection: 'row',
    flexWrap: 'wrap',
    overflow: 'hidden',
  },
});
